def solve_8way(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find edge zeros
    edge_zeros = set()
    for r in range(rows):
        if grid[r][0] == 0: edge_zeros.add((r, 0))
        if grid[r][cols-1] == 0: edge_zeros.add((r, cols-1))
    for c in range(cols):
        if grid[0][c] == 0: edge_zeros.add((0, c))
        if grid[rows-1][c] == 0: edge_zeros.add((rows-1, c))

    # BFS from edge zeros using 8-connectivity
    visited = set(edge_zeros)
    q = list(edge_zeros)
    while q:
        r, c = q.pop(0)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr != 0 or dc != 0:  # Not same cell
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))

    # Find interior regions (0s not connected to edge)
    filler_values = {}
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in visited:
                # Found new interior region
                region = []
                q_r = [(r, c)]
                visited.add((r, c))  # Mark as processed
                while q_r:
                    cr, cc = q_r.pop(0)
                    region.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr != 0 or dc != 0:
                                nr, nc = cr+dr, cc+dc
                                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0 and (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                    q_r.append((nr, nc))

                # Calculate fill based on dimensions
                br = [rr for rr, _ in region]
                bc = [cc for _, cc in region]
                h = max(br) - min(br) + 1
                w = max(bc) - min(bc) + 1
                fill = 14 - 2 * min(h, w)
                filler_values[fill] = fill
                for rr, cc in region:
                    result[rr][cc] = fill

    return result

