# Save transform to task-7737f424.py
transform_code = '''from collections import deque

def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # 8-way flood fill from edge to find exterior
    edge_zeros = set()
    for r in range(rows):
        if grid[r][0] == 0: edge_zeros.add((r, 0))
        if grid[r][cols-1] == 0: edge_zeros.add((r, cols-1))
    for c in range(cols):
        if grid[0][c] == 0: edge_zeros.add((0, c))
        if grid[rows-1][c] == 0: edge_zeros.add((rows-1, c))

    exterior = set(edge_zeros)
    q = deque(list(edge_zeros))
    while q:
        r, c = q.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr != 0 or dc != 0:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                        if (nr, nc) not in exterior:
                            exterior.add((nr, nc))
                            q.append((nr, nc))

    # Find interior 0s not reachable by 8-way from edge
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in exterior and (r, c) not in visited:
                # Start flood fill to map entire component
                component = set()
                q_comp = deque([(r, c)])
                component.add((r, c))
                while q_comp:
                    cr, cc = q_comp.popleft()
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr != 0 or dc != 0:
                                nr, nc = cr+dr, cc+dc
                                if 0 <= nr < rows and 0 <= nc < cols:
                                    if grid[nr][nc] == 0 and (nr, nc) not in exterior and (nr, nc) not in component:
                                        component.add((nr, nc))
                                        q_comp.append((nr, nc))

                # Calculate wall size based on component bbox
                r1, r2 = min(x[0] for x in component), max(x[0] for x in component)
                c1, c2 = min(x[1] for x in component), max(x[1] for x in component)
                wall_h = r2 - r1 + 3  # interior height + 2 wall thickness
                wall_w = c2 - c1 + 3  # interior width + 2 wall thickness
                wall_min = min(wall_h, wall_w)

                # Fill value formula
                fill = 25 // wall_min
                if wall_min == 5:
                    fill -= 1

                # Fill component
                for rr, cc in component:
                    result[rr][cc] = fill

    return result
'''

